style.css:
/* Midnight Focus — K12 Öğrenci */
:root {
  /* Renkleri buradan değiştirebilirsin */
  --my-bg: #101116;
  --my-panel: #191b24;
  --my-card: #20232e;
  --my-text: #e6e8f0;
  --my-muted: #9296a7;
  --my-accent: #8b83ff;
  --my-border: #303340;
}

/* Ana arka plan */
html,
body {
  background: var(--my-bg) !important;
  color: var(--my-text) !important;
}

/* Genel metinler */
body,
p,
span,
label,
li,
h1, h2, h3, h4, h5, h6 {
  color: var(--my-text) !important;
}

/* Paneller ve kartlar */
main,
section,
article,
aside,
[class*="card"],
[class*="Card"],
[class*="panel"],
[class*="Panel"],
[class*="container"] {
  background-color: var(--my-panel) !important;
  border-color: var(--my-border) !important;
  border-radius: 12px !important;
}

/* Bağlantılar */
a {
  color: var(--my-accent) !important;
}

/* Form alanları */
input,
textarea,
select {
  background: var(--my-card) !important;
  color: var(--my-text) !important;
  border: 1px solid var(--my-border) !important;
  border-radius: 9px !important;
}

/* Butonlar */
button {
  border-radius: 9px !important;
}

/* Tablolar */
table,
tr,
td,
th {
  background-color: var(--my-panel) !important;
  color: var(--my-text) !important;
  border-color: var(--my-border) !important;
}

/* Görseller */
img {
  border-radius: 8px;
}
